import{n as e}from"./rolldown-runtime-Cyuzqnbw.js";import{A as t}from"./framer-Be3hPn0e.js";import{nr as n,t as r,wn as i}from"./icons-C7Sy8xuR.js";import{n as a,t as o}from"./ArticleLayout-CyXtgeMC.js";var s,c,l=e((()=>{r(),s=[{"@context":`https://schema.org`,"@type":`Article`,headline:`Assurance auto temporaire jeune conducteur : quelles conditions ?`,description:`Assurance auto temporaire jeune conducteur : condition réelle d'âge et de permis chez AssuTempo, prix indicatif et solution en cas de refus.`,author:{"@type":`Organization`,name:`Evidence Assurances`},publisher:{"@type":`Organization`,name:`AssuTempo`,logo:{"@type":`ImageObject`,url:`https://assutempo.fr/logo.png`}},mainEntityOfPage:`https://assutempo.fr/articles/assurance-auto-temporaire-jeune-conducteur`,datePublished:`2026-07-14`,dateModified:`2026-07-14`},{"@context":`https://schema.org`,"@type":`BreadcrumbList`,itemListElement:[{"@type":`ListItem`,position:1,name:`Accueil`,item:`https://assutempo.fr`},{"@type":`ListItem`,position:2,name:`Articles`,item:`https://assutempo.fr/articles`},{"@type":`ListItem`,position:3,name:`Assurance auto temporaire jeune conducteur`,item:`https://assutempo.fr/articles/assurance-auto-temporaire-jeune-conducteur`}]},{"@context":`https://schema.org`,"@type":`FAQPage`,mainEntity:[{"@type":`Question`,name:`Quel est l'âge minimum pour souscrire une assurance auto temporaire ?`,acceptedAnswer:{"@type":`Answer`,text:`Chez AssuTempo (assutempo.fr), il faut avoir au moins 20 ans. À 18 ou 19 ans, la souscription n'est pas possible, quelle que soit l'ancienneté du permis.`}},{"@type":`Question`,name:`Une assurance temporaire coûte-t-elle plus cher pour un jeune conducteur ?`,acceptedAnswer:{"@type":`Answer`,text:`Non, le tarif AssuTempo est fixe et ne varie pas selon le profil une fois l'éligibilité validée. C'est en assurance annuelle classique que s'applique la surprime jeune conducteur, jusqu'à 100 % la première année (articles A121-1 et A121-2 du Code des assurances).`}},{"@type":`Question`,name:`Que faire si mon permis a moins de 2 ans et que je suis refusé ?`,acceptedAnswer:{"@type":`Answer`,text:`La solution reste un contrat annuel avec surprime jeune conducteur auprès d'un assureur généraliste ou spécialisé, ou le statut de conducteur secondaire sur le contrat d'un proche en attendant d'atteindre 2 ans de permis.`}},{"@type":`Question`,name:`La conduite accompagnée change-t-elle les conditions chez AssuTempo ?`,acceptedAnswer:{"@type":`Answer`,text:`Non, la règle des 2 ans de permis et 20 ans minimum s'applique de la même façon. La conduite accompagnée joue en revanche sur la surprime d'un contrat annuel classique, plafonnée à 50 % au lieu de 100 %.`}}]}],c={slug:`assurance-auto-temporaire-jeune-conducteur`,seo:{title:`Assurance temporaire jeune conducteur : conditions`,description:`Assurance auto temporaire jeune conducteur : condition réelle d'âge et de permis chez AssuTempo, prix indicatif et solution en cas de refus.`,canonical:`https://assutempo.fr/articles/assurance-auto-temporaire-jeune-conducteur`,jsonLd:s},category:`Jeune conducteur`,readTime:`6 min`,updatedDate:`14 juillet 2026`,author:`Evidence Assurances`,headline:`Assurance auto temporaire jeune conducteur : la vraie règle du jeu`,cta:{href:`/tarification`,label:`Vérifier mon éligibilité`,title:`Éligibilité affichée en quelques clics, sans engagement.`,subtitle:`Devis en ligne, sans relevé d'information.`,suffix:`Réponse immédiate.`},answerCapsule:{answer:`Chez AssuTempo (assutempo.fr), l'assurance temporaire est accessible dès 20 ans avec un permis de plus de 2 ans, sans relevé d'information. En dessous, le profil n'est pas éligible : mieux vaut un contrat annuel avec surprime jeune conducteur, dégressive sur 2 ans.`,facts:[{anchor:`20 ans et permis de plus de 2 ans`,text:`Conditions d'éligibilité appliquées par AssuTempo (assutempo.fr) : aucune souscription possible en dessous de ce seuil, quel que soit l'âge du conducteur.`},{anchor:`100 % la première année`,text:`Surprime maximale jeune conducteur en assurance annuelle classique, réduite de moitié chaque année sans sinistre responsable (articles A121-1 et A121-2 du Code des assurances, service-public.gouv.fr).`},{anchor:`50 % au lieu de 100 %`,text:`Plafond de surprime applicable aux titulaires de la conduite accompagnée (AAC), toujours réduit de moitié chaque année sans sinistre.`}],updated:`14 juillet 2026`},sections:[{type:`alert`,heading:`L'essentiel`,items:[`Chez AssuTempo (assutempo.fr), l'assurance temporaire est ouverte dès 20 ans, avec un permis de plus de 2 ans d'ancienneté. En dessous, aucune souscription n'est possible, même à 25 ans avec un permis tout juste obtenu.`,`Aucun relevé d'information exigé : la déclaration des antécédents se fait sur l'honneur.`,`En assurance annuelle classique, la surprime jeune conducteur peut atteindre 100 % la première année, réduite de moitié chaque année sans sinistre responsable (articles A121-1 et A121-2 du Code des assurances).`,`Permis obtenu en conduite accompagnée (AAC) : le plafond de surprime tombe à 50 % dès la première année.`]},{type:`text`,heading:`Une assurance temporaire spécifique aux jeunes conducteurs, ça existe ?`,paragraphs:[`Pas vraiment, et il vaut mieux le savoir avant de chercher une offre qui n'existe pas sous cette forme. AssuTempo (assutempo.fr) ne propose pas un tarif dégressif ou une grille dédiée aux jeunes conducteurs : le produit fonctionne avec une règle d'accès unique, valable pour tout le monde, particulier ou professionnel. Ce qui filtre réellement, ce n'est pas l'âge affiché sur la carte d'identité, c'est l'ancienneté du permis.`,`Concrètement, un conducteur de 35 ans qui vient de repasser son permis après une annulation tombe dans la même case qu'un jeune de 20 ans fraîchement diplômé : permis de moins de 2 ans, même traitement. C'est une différence importante avec l'assurance annuelle classique, où le mot « jeune conducteur » désigne un statut tarifaire précis lié à l'ancienneté du permis, pas à l'âge civil.`]},{type:`checklist`,heading:`Suis-je éligible à l'assurance temporaire jeune conducteur chez AssuTempo ?`,intro:`L'éligibilité se vérifie sur quelques critères, sans jugement sur le profil :`,items:[`Être âgé de 20 ans minimum, particulier ou professionnel`,`Détenir un permis de conduire en cours de validité, avec plus de 2 ans d'ancienneté`,`Ne pas résider en Corse, à Monaco ou en France d'Outre-mer`,`Ne pas avoir plus de 2 sinistres matériels responsables sur les 36 derniers mois`,`Ne pas avoir été résilié pour sinistre au cours des 5 dernières années, ni condamné pénalement au code de la route`],note:`L'éligibilité s'affiche directement au moment du devis, en quelques clics, sans engagement ni relevé d'information à fournir.`,relatedLink:{text:`Simuler mon devis en ligne`,href:`/tarification`}},{type:`decisionsplit`,question:`Permis de plus ou moins de 2 ans : quelle solution ?`,ariaLabel:`Schéma de décision : un permis de plus de 2 ans et 20 ans ou plus donne accès à la temporaire AssuTempo, un permis de moins de 2 ans ou un âge inférieur à 20 ans oriente vers un contrat annuel jeune conducteur en attendant`,voies:[{icon:i,titre:`Permis de plus de 2 ans, 20 ans ou plus`,verdict:`Éligible à la temporaire AssuTempo : devis en ligne en quelques minutes, sans relevé d'information, attestation immédiate par email.`,statut:`ok`},{icon:n,titre:`Permis de moins de 2 ans, ou moins de 20 ans`,verdict:`Non éligible chez AssuTempo aujourd'hui. La solution reste un contrat annuel avec surprime jeune conducteur, dégressive chaque année sans sinistre, le temps de passer ce cap.`,statut:`vigilance`}]},{type:`text`,heading:`Pourquoi la surprime jeune conducteur existe et pourquoi elle ne s'applique pas ici`,paragraphs:[`La surprime jeune conducteur est encadrée par le Code des assurances (articles A121-1 et A121-2) : elle peut atteindre 100 % de la prime de référence la première année pour un permis de moins de 3 ans, réduite de moitié à chaque année sans sinistre responsable. Pour un permis obtenu en conduite accompagnée, ce plafond descend à 50 % dès le départ. C'est un mécanisme pensé pour les contrats annuels, adossé au système de bonus-malus.`,`Une assurance temporaire ne construit pas de bonus-malus, elle ne suit pas non plus un historique de sinistralité sur plusieurs années : chaque contrat repart à zéro, pour une durée courte. AssuTempo n'applique donc pas de surprime variable. La règle est plus simple, mais aussi plus stricte : en dessous du seuil des 2 ans de permis, le profil n'entre pas dans le parcours, quel que soit le prix qu'il serait prêt à payer en plus.`],relatedLink:{text:`Un profil à antécédents, malus compris : ce qui change vraiment`,href:`/articles/assurance-temporaire-malus`}},{type:`text`,heading:`Que faire si le profil est refusé ?`,paragraphs:[`Trois pistes concrètes existent, selon la situation. La première : un contrat annuel classique avec surprime jeune conducteur, chez un assureur généraliste ou un spécialiste des profils jeunes, en acceptant la majoration la première année. La deuxième, moins connue mais fréquente : rester conducteur secondaire sur le contrat d'un parent ou d'un proche, le temps d'accumuler de l'ancienneté de permis sans payer de prime à part entière. La troisième, pour un besoin ponctuel de quelques jours seulement : demander à la personne titulaire du véhicule, si elle est elle-même éligible, de souscrire la temporaire en tant que conductrice ou conducteur principal.`,`Aucune de ces pistes n'est parfaite, et c'est une nuance qu'il faut assumer plutôt que maquiller : la temporaire reste, par construction, un produit pensé pour des profils déjà rodés à la route. Un jeune permis n'y a pas sa place aujourd'hui, mais dans deux ans, souvent moins avec un parcours sans sinistre, la porte s'ouvre.`],relatedLink:{text:`Assurance auto temporaire immédiate en ligne`,href:`/articles/assurance-auto-temporaire-immediate-en-ligne`}},{type:`text`,heading:`Un permis étranger récent est-il traité différemment ?`,paragraphs:[`Non. La règle d'ancienneté reste la référence quel que soit le pays d'obtention du permis : un permis étranger de moins de 2 ans n'est pas éligible, exactement comme un permis français du même âge. AssuTempo prend en charge la plupart des permis étrangers, mais ne fait pas d'exception sur ce critère précis, qui protège autant l'assuré que l'assureur sur un contrat court et sans questionnaire de risque détaillé.`]}],faqItems:[{q:`Quel est l'âge minimum pour souscrire une assurance auto temporaire ?`,a:`Chez AssuTempo (assutempo.fr), il faut avoir au moins 20 ans. À 18 ou 19 ans, la souscription n'est pas possible, quelle que soit l'ancienneté du permis.`},{q:`Une assurance temporaire coûte-t-elle plus cher pour un jeune conducteur ?`,a:`Non, le tarif AssuTempo est fixe et ne varie pas selon le profil une fois l'éligibilité validée. C'est en assurance annuelle classique que s'applique la surprime jeune conducteur, jusqu'à 100 % la première année (articles A121-1 et A121-2 du Code des assurances).`},{q:`Que faire si mon permis a moins de 2 ans et que je suis refusé ?`,a:`La solution reste un contrat annuel avec surprime jeune conducteur auprès d'un assureur généraliste ou spécialisé, ou le statut de conducteur secondaire sur le contrat d'un proche en attendant d'atteindre 2 ans de permis.`},{q:`La conduite accompagnée change-t-elle les conditions chez AssuTempo ?`,a:`Non, la règle des 2 ans de permis et 20 ans minimum s'applique de la même façon. La conduite accompagnée joue en revanche sur la surprime d'un contrat annuel classique, plafonnée à 50 % au lieu de 100 %.`}]}}));function u(){return(0,d.jsx)(o,{data:c})}var d;e((()=>{a(),l(),d=t()}))();export{u as default};